local i
for i = 1, #TELEPORTS do
    local point = TELEPORTS[i]
    local command = string.format(".go xyz %s %s %s %d", tostring(point.x), tostring(point.y), tostring(point.z), point.map)
    if point.o ~= nil then
        command = command .. " " .. tostring(point.o)
    end
    table.insert(TortoiseGMManager.commands, {
        id = point.id,
        category = "travel",
        label = point.zone .. ": " .. point.point,
        command = command,
        detail = "Teleport to " .. point.point .. " in " .. point.zone .. " (" .. point.category .. ").",
        access = TELEPORT_ACCESS,
        direct = true,
        arguments = {},
        legacyCommands = {},
    })
end
